{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "CZC25146, a morpholine-containing aminopyrimidine kinase inhibitor, showed negligible total brain/plasma AUC in mice, directly indicating poor BBB permeability in a scaffold closely related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 8, containing a morpholine amide and aminopyrimidine, had an unbound brain/unbound plasma AUC ratio of 0.11 in rat brain PK, demonstrating poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Inhibitor 6, with a morpholine amide and aminopyrimidine, had a Bu/Pu ratio of 0.08 in rats, confirming lack of meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Compound 4, a morpholine-containing pyrazolopyrimidine, had a brain-blood ratio of 0.07 in a mouse efficacy model, indicating limited CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Compound 70 had CSF concentration 2 nM versus unbound plasma 290 nM, attributed to high lipophilicity and poor passive permeability, supporting poor CNS exposure for a morpholine-containing analogue.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer in vivo and clinical analogues demonstrate negligible-to-poor brain penetration (Bu/Pu 0.07-0.17, CSF much lower than unbound plasma, impermeable BBB), and the query shares key morpholine, aminopyrimidine, and heteroaromatic features; therefore the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF PK data for the exact query molecule.",
    "No explicit P-gp/BCRP efflux transporter assay for the query.",
    "No human CNS exposure data for the query or exact close analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

